Just for additional context, this is how I am building these queries

```const buildPgSearchQuery = ({
  searchTerm,
}: {
  readonly searchTerm: string;
}) =&gt; {
  const cleanedPhrase = searchTerm.trim();

  if (!cleanedPhrase) {
    return createPgSearchQuery({ all: null });
  }

  const fieldConfigs = [
    { boost: 5, distance: 1, field: 'name' },
    { boost: 2, distance: 1, field: 'slug' },
    { boost: 2, distance: 1, field: 'namespace_slug' },
    { boost: 1, distance: 0, field: 'description' },
    { boost: 1, distance: 1, field: 'github_repository_full_name' },
    { boost: 0.5, distance: 1, field: 'github_repository_url' },
  ];

  const shouldQueries: PgSearchQuery[] = [];

  // Add exact matches with very high boost for name
  for (const field of ['name']) {
    shouldQueries.push({
      boost: {
        factor: 20,
        query: {
          term: {
            field,
            value: cleanedPhrase.toLowerCase(),
          },
        },
      },
    });
  }

  // Add main queries for each field
  for (const { boost, distance, field } of fieldConfigs) {
    // Fuzzy match
    shouldQueries.push({
      boost: {
        factor: boost,
        query: {
          match: {
            distance,
            field,
            value: cleanedPhrase,
          },
        },
      },
    });

    // Prefix match for better partial word handling
    shouldQueries.push({
      boost: {
        factor: boost * 1.5,
        query: {
          phrase_prefix: {
            field,
            max_expansions: 50,
            phrases: cleanedPhrase.toLowerCase().split(/\s+/u),
          },
        },
      },
    });
  }

  return createPgSearchQuery({
    boolean: {
      should: shouldQueries,
    },
  });
};```

